ew = {2, 3, 4};

edgestyle = Thread[
  el -> (Directive[
      CapForm["Round"],
      Thickness[.02 + .04 #],
      ColorData["SolarColors"][#]
    ] & /@ Rescale[ew])
];

g2 = Graph[el, EdgeWeight -> ew, EdgeStyle -> edgestyle];
