n = 0;
list = {};
r := RandomReal[];
coin := RandomChoice[{True, False}];

While[n < 10000,
  {x, y} = {r, r};
  If[((x - .5)^2 + (y - .5)^2 <= .1 || coin),
    AppendTo[list, {x, y}];
    n++
