A fast way to avoid the extra blank lines is to skip the nested `Export` call and write the CSV yourself, line by line. The accepted approach is:

writeYourCSV[file_String, list_List?MatrixQ] :=
 With[{str = OpenWrite[file, PageWidth -> Infinity], len = Length[list[[1]]]},
  Scan[
   Write[str,
    Sequence @@ (Flatten[
       Table[{FortranForm[#[[i]]], OutputForm[","]}, {i, len - 1}]
     ]) ~Join~ {FortranForm[#[[len]]]}] &,
   list];
